contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker; takes arbitrary inputs
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(true);

        // Call transfer and observe whether it reverts.
        bool reverted;
        bool ret;
        uint balBefore = address(c).balance;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // If it did not revert then it must have returned true, and c's balance must be unchanged.
        assert(reverted || (ret == true && address(c).balance == balBefore));
    }

    receive() external payable { }
}

